19	package org.apache.hadoop.fs.s3a.impl;
20	
21	import java.io.IOException;
22	import java.util.ArrayList;
23	import java.util.List;
24	import java.util.Map;
25	import java.util.concurrent.CompletableFuture;
26	import java.util.concurrent.atomic.AtomicLong;
27	
28	import com.amazonaws.AmazonClientException;
29	import com.amazonaws.services.s3.model.DeleteObjectsRequest;
30	import com.amazonaws.services.s3.transfer.model.CopyResult;
31	import org.apache.hadoop.util.Lists;
32	import org.slf4j.Logger;
33	import org.slf4j.LoggerFactory;
34	
35	import org.apache.hadoop.fs.Path;
36	import org.apache.hadoop.fs.RemoteIterator;
37	import org.apache.hadoop.fs.s3a.RenameFailedException;
38	import org.apache.hadoop.fs.s3a.Retries;
39	import org.apache.hadoop.fs.s3a.S3AFileStatus;
40	import org.apache.hadoop.fs.s3a.S3ALocatedFileStatus;
41	import org.apache.hadoop.fs.s3a.S3AReadOpContext;
42	import org.apache.hadoop.fs.s3a.S3ObjectAttributes;
43	import org.apache.hadoop.fs.s3a.Tristate;
44	import org.apache.hadoop.fs.s3a.s3guard.MetadataStore;
45	import org.apache.hadoop.fs.s3a.s3guard.RenameTracker;
46	import org.apache.hadoop.util.DurationInfo;
47	import org.apache.hadoop.util.OperationDuration;
48	
49	import static org.apache.hadoop.fs.store.audit.AuditingFunctions.callableWithinAuditSpan;
50	import static org.apache.hadoop.util.Preconditions.checkNotNull;
51	import static org.apache.hadoop.fs.s3a.Constants.FS_S3A_BLOCK_SIZE;
52	import static org.apache.hadoop.fs.s3a.S3AUtils.objectRepresentsDirectory;
53	import static org.apache.hadoop.fs.s3a.impl.CallableSupplier.submit;
54	import static org.apache.hadoop.fs.s3a.impl.CallableSupplier.waitForCompletion;
55	import static org.apache.hadoop.fs.s3a.impl.InternalConstants.DEFAULT_BLOCKSIZE;
56	import static org.apache.hadoop.fs.s3a.impl.InternalConstants.RENAME_PARALLEL_LIMIT;
57	
58	/**
59	 * A parallelized rename operation which updates the metastore in the
60	 * process, through whichever {@link RenameTracker} the store provides.
61	 * <p></p>
62	 * The parallel execution is in groups of size
63	 * {@link InternalConstants#RENAME_PARALLEL_LIMIT}; it is only
64	 * after one group completes that the next group is initiated.
65	 * <p></p>
66	 * Once enough files have been copied that they meet the
67	 * {@link InternalConstants#MAX_ENTRIES_TO_DELETE} threshold, a delete
68	 * is initiated.
69	 * If it succeeds, the rename continues with the next group of files.
70	 * <p></p>
71	 * The RenameTracker has the task of keeping the metastore up to date
72	 * as the rename proceeds.
73	 * <p></p>
74	 * Directory Markers which have child entries are never copied; only those
75	 * which represent empty directories are copied in the rename.
76	 * The {@link DirMarkerTracker} tracks which markers must be copied, and
77	 * which can simply be deleted from the source.
78	 * As a result: rename always purges all non-leaf directory markers from
79	 * the copied tree. This is to ensure that even if a directory tree
80	 * is copied from an authoritative path to a non-authoritative one
81	 * there is never any contamination of the non-auth path with markers.
82	 * <p></p>
83	 * The rename operation implements the classic HDFS rename policy of
84	 * rename(file, dir) renames the file under the directory.
85	 * <p></p>
86	 *
87	 * There is <i>no</i> validation of input and output paths.
88	 * Callers are required to themselves verify that destination is not under
89	 * the source, above the source, the source itself, etc, etc.
90	 */
91	public class RenameOperation extends ExecutingStoreOperation<Long> {
92	
93	  private static final Logger LOG = LoggerFactory.getLogger(
94	      RenameOperation.class);
95	
96	  private final Path sourcePath;
97	
98	  private final String sourceKey;
99	
100	  private final S3AFileStatus sourceStatus;
101	
102	  private final Path destPath;
103	
104	  private final String destKey;
105	
106	  private final S3AFileStatus destStatus;
107	
108	  /**
109	   * Callbacks into the filesystem.
110	   */
111	  private final OperationCallbacks callbacks;
112	
113	  /**
114	   * Counter of bytes copied.
115	   */
116	
117	  private final AtomicLong bytesCopied = new AtomicLong();
118	
119	  /**
120	   * Page size for bulk deletes.
121	   */
122	  private final int pageSize;
123	
124	  /**
125	   * Rename tracker.
126	   */
127	  private RenameTracker renameTracker;
128	
129	  /**
130	   * List of active copies.
131	   */
132	  private final List<CompletableFuture<Path>> activeCopies =
133	      new ArrayList<>(RENAME_PARALLEL_LIMIT);
134	
135	  /**
136	   * list of keys to delete on the next (bulk) delete call.
137	   */
138	  private final List<DeleteObjectsRequest.KeyVersion> keysToDelete =
139	      new ArrayList<>();
140	
141	  /**
142	   * List of paths to delete, which will be passed to the rename
143	   * tracker after the deletion succeeds.
144	   */
145	  private final List<Path> pathsToDelete = new ArrayList<>();
146	
147	  private final long blocksize;
148	
149	  /**
150	   * Initiate the rename.
151	   *
152	   * @param storeContext store context
153	   * @param sourcePath source path
154	   * @param sourceKey key of source
155	   * @param sourceStatus pre-fetched source status
156	   * @param destPath destination path.
157	   * @param destKey destination key
158	   * @param destStatus destination status.
159	   * @param callbacks callback provider
160	   * @param pageSize size of delete requests
161	   */
162	  public RenameOperation(
163	      final StoreContext storeContext,
164	      final Path sourcePath,
165	      final String sourceKey,
166	      final S3AFileStatus sourceStatus,
167	      final Path destPath,
168	      final String destKey,
169	      final S3AFileStatus destStatus,
170	      final OperationCallbacks callbacks,
171	      final int pageSize) {
172	    super(storeContext);
173	    this.sourcePath = sourcePath;
174	    this.sourceKey = sourceKey;
175	    this.sourceStatus = sourceStatus;
176	    this.destPath = destPath;
177	    this.destKey = destKey;
178	    this.destStatus = destStatus;
179	    this.callbacks = callbacks;
180	    blocksize = storeContext.getConfiguration()
181	        .getLongBytes(FS_S3A_BLOCK_SIZE, DEFAULT_BLOCKSIZE);
182	    this.pageSize = pageSize;
183	  }
184	
185	  /**
186	   * Wait for the active copies to complete then reset the list.
187	   * @param reason for messages
188	   * @throws IOException if one of the called futures raised an IOE.
189	   * @throws RuntimeException if one of the futures raised one.
190	   */
191	  @Retries.OnceTranslated
192	  private void completeActiveCopies(String reason) throws IOException {
193	    LOG.debug("Waiting for {} active copies to complete: {}",
194	        activeCopies.size(), reason);
195	    waitForCompletion(activeCopies);
196	    activeCopies.clear();
197	  }
198	
199	  /**
200	   * Queue an object for deletion.
201	   * <p></p>
202	   * This object will be deleted when the next page of objects to delete
203	   * is posted to S3. Therefore, the COPY must have finished
204	   * before that deletion operation takes place.
205	   * This is managed by:
206	   * <ol>
207	   *   <li>
208	   *     The delete operation only being executed once all active
209	   *     copies have completed.
210	   *   </li>
211	   *   <li>
212	   *     Only queuing objects here whose copy operation has
213	   *     been submitted and so is in that thread pool.
214	   *   </li>
215	   *   <li>
216	   *     If a path is supplied, then after the delete is executed
217	   *     (and completes) the rename tracker from S3Guard will be
218	   *     told of its deletion. Do not set this for directory
219	   *     markers with children, as it may mistakenly add
220	   *     tombstones into the table.
221	   *   </li>
222	   * </ol>
223	   * This method must only be called from the primary thread.
224	   * @param path path to the object.
225	   * @param key key of the object.
226	   */
227	  private void queueToDelete(Path path, String key) {
228	    LOG.debug("Queueing to delete {}", path);
229	    if (path != null) {
230	      pathsToDelete.add(path);
231	    }
232	    keysToDelete.add(new DeleteObjectsRequest.KeyVersion(key));
233	  }
234	
235	  /**
236	   * Queue a list of markers for deletion.
237	   * <p></p>
238	   * no-op if the list is empty.
239	   * <p></p>
240	   * See {@link #queueToDelete(Path, String)} for
241	   * details on safe use of this method.
242	   *
243	   * @param markersToDelete markers
244	   */
245	  private void queueToDelete(
246	      List<DirMarkerTracker.Marker> markersToDelete) {
247	    markersToDelete.forEach(m -> queueToDelete(
248	        null,
249	        m.getKey()));
250	  }
251	
252	  /**
253	   * Queue a single marker for deletion.
254	   * <p></p>
255	   * See {@link #queueToDelete(Path, String)} for
256	   * details on safe use of this method.
257	   *
258	   * @param marker markers
259	   */
260	  private void queueToDelete(final DirMarkerTracker.Marker marker) {
261	    queueToDelete(marker.getPath(), marker.getKey());
262	  }
263	
264	  /**
265	   * Block waiting for ay active copies to finish
266	   * then delete all queued keys + paths to delete.
267	   * @param reason reason for logs
268	   * @throws IOException failure.
269	   */
270	  @Retries.RetryTranslated
271	  private void completeActiveCopiesAndDeleteSources(String reason)
272	      throws IOException {
273	    completeActiveCopies(reason);
274	    removeSourceObjects(
275	        keysToDelete,
276	        pathsToDelete);
277	    // now reset the lists.
278	    keysToDelete.clear();
279	    pathsToDelete.clear();
280	  }
281	
282	  @Retries.RetryMixed
283	  public Long execute() throws IOException {
284	    executeOnlyOnce();
285	    final StoreContext storeContext = getStoreContext();
286	    final MetadataStore metadataStore = checkNotNull(
287	        storeContext.getMetadataStore(),
288	        "No metadata store in context");
289	
290	    // Validation completed: time to begin the operation.
291	    // The store-specific rename tracker is used to keep the store
292	    // to date with the in-progress operation.
293	    // for the null store, these are all no-ops.
294	    renameTracker = metadataStore.initiateRenameOperation(
295	        storeContext,
296	        sourcePath, sourceStatus, destPath);
297	
298	    // The path to whichever file or directory is created by the
299	    // rename. When deleting markers all parents of
300	    // this path will need their markers pruned.
301	    Path destCreated = destPath;
302	
303	    // Ok! Time to start
304	    try {
305	      if (sourceStatus.isFile()) {
306	        // rename the file. The destination path will be different
307	        // from that passed in if the destination is a directory;
308	        // the final value is needed to completely delete parent markers
309	        // when they are not being retained.
310	        destCreated = renameFileToDest();
311	      } else {
312	        recursiveDirectoryRename();
313	      }
314	    } catch (AmazonClientException | IOException ex) {
315	      // rename failed.
316	      // block for all ongoing copies to complete, successfully or not
317	      try {
318	        completeActiveCopies("failure handling");
319	      } catch (IOException e) {
320	        // a failure to update the metastore after a rename failure is what
321	        // we'd see on a network problem, expired credentials and other
322	        // unrecoverable errors.
323	        // Downgrading to warn because an exception is already
324	        // about to be thrown.
325	        LOG.warn("While completing all active copies", e);
326	      }
327	      // notify the rename tracker of the failure
328	      throw renameTracker.renameFailed(ex);
329	    }
330	
331	    // At this point the rename has completed successfully in the S3 store.
332	    // Tell the metastore this fact and let it complete its changes
333	    renameTracker.completeRename();
334	
335	    callbacks.finishRename(sourcePath, destCreated);
336	    return bytesCopied.get();
337	  }
338	
339	  /**
340	   * The source is a file: rename it to the destination, which
341	   * will be under the current destination path if that is a directory.
342	   * @return the path of the object created.
343	   * @throws IOException failure
344	   */
345	  protected Path renameFileToDest() throws IOException {
346	    final StoreContext storeContext = getStoreContext();
347	    // the source is a file.
348	    Path copyDestinationPath = destPath;
349	    String copyDestinationKey = destKey;
350	    S3ObjectAttributes sourceAttributes =
351	        callbacks.createObjectAttributes(sourceStatus);
352	    S3AReadOpContext readContext = callbacks.createReadContext(sourceStatus);
353	    if (destStatus != null && destStatus.isDirectory()) {
354	      // destination is a directory: build the final destination underneath
355	      String newDestKey = maybeAddTrailingSlash(destKey);
356	      String filename = sourceKey.substring(
357	          storeContext.pathToKey(sourcePath.getParent()).length() + 1);
358	      newDestKey = newDestKey + filename;
359	      copyDestinationKey = newDestKey;
360	      copyDestinationPath = storeContext.keyToPath(newDestKey);
361	    }
362	    // destination either does not exist or is a file to overwrite.
363	    LOG.debug("rename: renaming file {} to {}", sourcePath,
364	        copyDestinationPath);
365	    copySourceAndUpdateTracker(
366	        sourcePath,
367	        sourceKey,
368	        sourceAttributes,
369	        readContext,
370	        copyDestinationPath,
371	        copyDestinationKey,
372	        false);
373	    bytesCopied.addAndGet(sourceStatus.getLen());
374	    // delete the source
375	    callbacks.deleteObjectAtPath(sourcePath, sourceKey, true, null);
376	    // and update the tracker
377	    renameTracker.sourceObjectsDeleted(Lists.newArrayList(sourcePath));
378	    return copyDestinationPath;
379	  }
380	
381	  /**
382	   * Execute a full recursive rename.
383	   * There is a special handling of directly markers here -only leaf markers
384	   * are copied. This reduces incompatibility "regions" across versions.
385	   * @throws IOException failure
386	   */
387	  protected void recursiveDirectoryRename() throws IOException {
388	    final StoreContext storeContext = getStoreContext();
389	
390	    LOG.debug("rename: renaming directory {} to {}", sourcePath, destPath);
391	
392	    // This is a directory-to-directory copy
393	    String dstKey = maybeAddTrailingSlash(destKey);
394	    String srcKey = maybeAddTrailingSlash(sourceKey);
395	
396	    // Verify dest is not a child of the source directory
397	    if (dstKey.startsWith(srcKey)) {
398	      throw new RenameFailedException(srcKey, dstKey,
399	          "cannot rename a directory to a subdirectory of itself ");
400	    }
401	
402	    if (destStatus != null
403	        && destStatus.isEmptyDirectory() == Tristate.TRUE) {
404	      // delete unnecessary fake directory at the destination.
405	      // this MUST be done before anything else so that
406	      // rollback code doesn't get confused and insert a tombstone
407	      // marker.
408	      LOG.debug("Deleting fake directory marker at destination {}",
409	          destStatus.getPath());
410	      // Although the dir marker policy doesn't always need to do this,
411	      // it's simplest just to be consistent here.
412	      // note: updates the metastore as well a S3.
413	      callbacks.deleteObjectAtPath(destStatus.getPath(), dstKey, false, null);
414	    }
415	
416	    Path parentPath = storeContext.keyToPath(srcKey);
417	
418	    // Track directory markers so that we know which leaf directories need to be
419	    // recreated
420	    DirMarkerTracker dirMarkerTracker = new DirMarkerTracker(parentPath,
421	        false);
422	
423	    final RemoteIterator<S3ALocatedFileStatus> iterator =
424	        callbacks.listFilesAndDirectoryMarkers(parentPath,
425	            sourceStatus,
426	            true,
427	            true);
428	    while (iterator.hasNext()) {
429	      // get the next entry in the listing.
430	      S3ALocatedFileStatus child = iterator.next();
431	      LOG.debug("To rename {}", child);
432	      // convert it to an S3 key.
433	      String k = storeContext.pathToKey(child.getPath());
434	      // possibly adding a "/" if it represents directory and it does
435	      // not have a trailing slash already.
436	      String key = (child.isDirectory() && !k.endsWith("/"))
437	          ? k + "/"
438	          : k;
439	      // the source object to copy as a path.
440	      Path childSourcePath = storeContext.keyToPath(key);
441	
442	      List<DirMarkerTracker.Marker> markersToDelete;
443	
444	      boolean isMarker = key.endsWith("/");
445	      if (isMarker) {
446	        // add the marker to the tracker.
447	        // it will not be deleted _yet_ but it may find a list of parent
448	        // markers which may now be deleted.
449	        markersToDelete = dirMarkerTracker.markerFound(
450	            childSourcePath, key, child);
451	      } else {
452	        // it is a file.
453	        // note that it has been found -this may find a list of parent
454	        // markers which may now be deleted.
455	        markersToDelete = dirMarkerTracker.fileFound(
456	            childSourcePath, key, child);
457	        // the destination key is that of the key under the source tree,
458	        // remapped under the new destination path.
459	        String newDestKey =
460	            dstKey + key.substring(srcKey.length());
461	        Path childDestPath = storeContext.keyToPath(newDestKey);
462	
463	        // mark the source file for deletion on a successful copy.
464	        queueToDelete(childSourcePath, key);
465	          // now begin the single copy
466	        CompletableFuture<Path> copy = initiateCopy(child, key,
467	            childSourcePath, newDestKey, childDestPath);
468	        activeCopies.add(copy);
469	        bytesCopied.addAndGet(sourceStatus.getLen());
470	      }
471	      // add any markers to delete to the operation so they get cleaned
472	      // incrementally
473	      queueToDelete(markersToDelete);
474	      // and trigger any end of loop operations
475	      endOfLoopActions();
476	    } // end of iteration through the list
477	
478	    // finally process remaining directory markers
479	    copyEmptyDirectoryMarkers(srcKey, dstKey, dirMarkerTracker);
480	
481	    // await the final set of copies and their deletion
482	    // This will notify the renameTracker that these objects
483	    // have been deleted.
484	    completeActiveCopiesAndDeleteSources("final copy and delete");
485	
486	    // We moved all the children, now move the top-level dir
487	    // Empty directory should have been added as the object summary
488	    renameTracker.moveSourceDirectory();
489	  }
490	
491	  /**
492	   * Operations to perform at the end of every loop iteration.
493	   * <p></p>
494	   * This may block the thread waiting for copies to complete
495	   * and/or delete a page of data.
496	   */
497	  private void endOfLoopActions() throws IOException {
498	    if (keysToDelete.size() == pageSize) {
499	      // finish ongoing copies then delete all queued keys.
500	      completeActiveCopiesAndDeleteSources("paged delete");
501	    } else {
502	      if (activeCopies.size() == RENAME_PARALLEL_LIMIT) {
503	        // the limit of active copies has been reached;
504	        // wait for completion or errors to surface.
505	        LOG.debug("Waiting for active copies to complete");
506	        completeActiveCopies("batch threshold reached");
507	      }
508	    }
509	  }
510	
511	  /**
512	   * Process all directory markers at the end of the rename.
513	   * All leaf markers are queued to be copied in the store;
514	   * this updates the metastore tracker as it does so.
515	   * <p></p>
516	   * Why not simply create new markers? All the metadata
517	   * gets copied too, so if there was anything relevant then
518	   * it would be preserved.
519	   * <p></p>
520	   * At the same time: markers aren't valued much and may
521	   * be deleted without any safety checks -so if there was relevant
522	   * data it is at risk of destruction at any point.
523	   * If there are lots of empty directory rename operations taking place,
524	   * the decision to copy the source may need revisiting.
525	   * Be advised though: the costs of the copy not withstanding,
526	   * it is a lot easier to have one single type of scheduled copy operation
527	   * than have copy and touch calls being scheduled.
528	   * <p></p>
529	   * The duration returned is the time to initiate all copy/delete operations,
530	   * including any blocking waits for active copies and paged deletes
531	   * to execute. There may still be outstanding operations
532	   * queued by this method -the duration may be an underestimate
533	   * of the time this operation actually takes.
534	   *
535	   * @param srcKey source key with trailing /
536	   * @param dstKey dest key with trailing /
537	   * @param dirMarkerTracker tracker of markers
538	   * @return how long it took.
539	   */
540	  private OperationDuration copyEmptyDirectoryMarkers(
541	      final String srcKey,
542	      final String dstKey,
543	      final DirMarkerTracker dirMarkerTracker) throws IOException {
544	    // directory marker work.
545	    LOG.debug("Copying markers from {}", dirMarkerTracker);
546	    final StoreContext storeContext = getStoreContext();
547	    Map<Path, DirMarkerTracker.Marker> leafMarkers =
548	        dirMarkerTracker.getLeafMarkers();
549	    Map<Path, DirMarkerTracker.Marker> surplus =
550	        dirMarkerTracker.getSurplusMarkers();
551	    // for all leaf markers: copy the original
552	    DurationInfo duration = new DurationInfo(LOG, false,
553	        "copying %d leaf markers with %d surplus not copied",
554	        leafMarkers.size(), surplus.size());
555	    for (DirMarkerTracker.Marker entry: leafMarkers.values()) {
556	      Path source = entry.getPath();
557	      String key = entry.getKey();
558	      String newDestKey =
559	          dstKey + key.substring(srcKey.length());
560	      Path childDestPath = storeContext.keyToPath(newDestKey);
561	      LOG.debug("copying dir marker from {} to {}", key, newDestKey);
562	
563	      activeCopies.add(
564	          initiateCopy(
565	              entry.getStatus(),
566	              key,
567	              source,
568	              newDestKey,
569	              childDestPath));
570	      queueToDelete(entry);
571	      // end of loop
572	      endOfLoopActions();
573	    }
574	    duration.close();
575	    return duration;
576	  }
577	
578	  /**
579	   * Initiate a copy operation in the executor.
580	   * @param source status of the source object.
581	   * @param key source key
582	   * @param childSourcePath source as a path.
583	   * @param newDestKey destination key
584	   * @param childDestPath destination path.
585	   * @return the future.
586	   */
587	  protected CompletableFuture<Path> initiateCopy(
588	      final S3ALocatedFileStatus source,
589	      final String key,
590	      final Path childSourcePath,
591	      final String newDestKey,
592	      final Path childDestPath) {
593	    S3ObjectAttributes sourceAttributes =
594	        callbacks.createObjectAttributes(
595	            source.getPath(),
596	            source.getEtag(),
597	            source.getVersionId(),
598	            source.getLen());
599	    // queue the copy operation for execution in the thread pool
600	    return submit(getStoreContext().getExecutor(),
601	        callableWithinAuditSpan(getAuditSpan(), () ->
602	            copySourceAndUpdateTracker(
603	                childSourcePath,
604	                key,
605	                sourceAttributes,
606	                callbacks.createReadContext(source),
607	                childDestPath,
608	                newDestKey,
609	                true)));
610	  }
611	
612	  /**
613	   * This invoked to copy a file or directory marker then update the
614	   * rename operation on success.
615	   * It may be called in its own thread.
616	   * @param sourceFile source path of the copy; may have a trailing / on it.
617	   * @param srcKey source key
618	   * @param srcAttributes status of the source object
619	   * @param destination destination as a qualified path.
620	   * @param destinationKey destination key
621	   * @param addAncestors should ancestors be added to the metastore?
622	   * @return the destination path.
623	   * @throws IOException failure
624	   */
625	  @Retries.RetryTranslated
626	  private Path copySourceAndUpdateTracker(
627	      final Path sourceFile,
628	      final String srcKey,
629	      final S3ObjectAttributes srcAttributes,
630	      final S3AReadOpContext readContext,
631	      final Path destination,
632	      final String destinationKey,
633	      final boolean addAncestors) throws IOException {
634	    long len = srcAttributes.getLen();
635	    CopyResult copyResult;
636	    try (DurationInfo ignored = new DurationInfo(LOG, false,
