182	   *
183	   * @param value any {@code long} value.
184	   * @return the same value cast to {@code int} if it is in the range of the
185	   *     {@code int} type, {@link Integer#MAX_VALUE} if it is too large,
186	   *     or {@link Integer#MIN_VALUE} if it is too small.
187	   */
188	  private static int saturatedCast(long value) {
189	    if (value > Integer.MAX_VALUE) {
190	      return Integer.MAX_VALUE;
191	    }
192	    if (value < Integer.MIN_VALUE) {
193	      return Integer.MIN_VALUE;
194	    }
195	    return (int) value;
196	  }
