198	  private static <T> boolean addAll(Collection<T> addTo,
199	      Iterator<? extends T> iterator) {
200	    if (addTo == null) {
201	      throw new NullPointerException();
202	    }
203	    if (iterator == null) {
204	      throw new NullPointerException();
205	    }
206	    boolean wasModified = false;
207	    while (iterator.hasNext()) {
208	      wasModified |= addTo.add(iterator.next());
209	    }
210	    return wasModified;
211	  }
