217	  /**
218	   * Adds all elements in {@code iterable} to {@code collection}.
219	   *
220	   * @return {@code true} if {@code collection} was modified as a result of
221	   *     this operation.
222	   */
223	  private static <T> boolean addAll(Collection<T> addTo,
224	      Iterable<? extends T> elementsToAdd) {
225	    if (elementsToAdd instanceof Collection) {
226	      Collection<? extends T> c = cast(elementsToAdd);
227	      return addTo.addAll(c);
228	    }
229	    if (elementsToAdd == null) {
230	      throw new NullPointerException();
231	    }
232	    return addAll(addTo, elementsToAdd.iterator());
